		});
		expect(workflow.analyze).toHaveBeenCalledWith(
			expect.objectContaining({
				originalName: 'geih.parquet',
				dataSource: { code: 'GEIH', name: 'GEIH', description: 'Labor survey' }
			})
		);
	});

